<?php
declare(strict_types=1);

require_once __DIR__.'/../../includes/lacms_operational_helpers.php';
requireLacmsPermission('lacms.agendas.view');

$pdo=db();$id=(int)($_GET['id']??0);
$q=$pdo->prepare(
 "SELECT a.*,c.name committee_name,o.name office_name,u.full_name created_name,
         fu.full_name finalized_name
  FROM lacms_agendas a
  LEFT JOIN committees c ON c.id=a.committee_id
  LEFT JOIN offices o ON o.id=a.office_id
  LEFT JOIN users u ON u.id=a.created_by
  LEFT JOIN users fu ON fu.id=a.finalized_by
  WHERE a.id=:id"
);$q->execute([':id'=>$id]);$agenda=$q->fetch();
if(!$agenda){setFlash('warning','Agenda not found.');redirect(appUrl('modules/agendas/index.php'));}

$items=$pdo->prepare(
 "SELECT i.*,li.reference_number legislative_reference,li.current_status legislative_status,
         su.full_name sponsor_name,pu.full_name presenter_name,c.name committee_name
  FROM lacms_agenda_items i
  LEFT JOIN legislative_items li ON li.id=i.legislative_item_id
  LEFT JOIN users su ON su.id=i.sponsor_user_id
  LEFT JOIN users pu ON pu.id=i.presenter_user_id
  LEFT JOIN committees c ON c.id=i.committee_id
  WHERE i.agenda_id=:id ORDER BY i.sequence_number,i.id"
);$items->execute([':id'=>$id]);$agendaItems=$items->fetchAll();

$history=$pdo->prepare(
 "SELECT h.*,u.full_name changed_name FROM lacms_agenda_history h
  LEFT JOIN users u ON u.id=h.changed_by
  WHERE h.agenda_id=:id ORDER BY h.created_at DESC,h.id DESC"
);$history->execute([':id'=>$id]);$historyRows=$history->fetchAll();

$docs=$pdo->prepare(
 "SELECT d.*,u.full_name uploaded_name,i.title item_title
  FROM lacms_agenda_documents d
  LEFT JOIN users u ON u.id=d.uploaded_by
  LEFT JOIN lacms_agenda_items i ON i.id=d.agenda_item_id
  WHERE d.agenda_id=:id ORDER BY d.uploaded_at DESC,d.id DESC"
);$docs->execute([':id'=>$id]);$documents=$docs->fetchAll();

$legislativeItems=$pdo->query(
 "SELECT li.id,li.reference_number,li.title,li.current_status
  FROM legislative_items li
  JOIN legislative_item_types t ON t.id=li.item_type_id
  WHERE li.deleted_at IS NULL
    AND t.code IN ('ordinance','resolution','proposal','executive_request','policy_matter')
  ORDER BY li.updated_at DESC LIMIT 300"
)->fetchAll();
$users=$pdo->query(
 "SELECT u.id,u.full_name FROM users u
  JOIN roles r ON r.id=u.role_id
  WHERE u.status='Active' AND u.deleted_at IS NULL
    AND r.name IN ('Administrator','Legislative Staff','Committee Member')
  ORDER BY u.full_name"
)->fetchAll();
$committees=$pdo->query("SELECT id,name FROM committees WHERE status='Active' ORDER BY name")->fetchAll();
$offices=$pdo->query("SELECT id,name FROM offices WHERE status='Active' ORDER BY name")->fetchAll();

$pageTitle=$agenda['agenda_reference'];$activeMenu='agendas';
$extraCss=[appUrl('assets/css/lacms-operational.css')];
include __DIR__.'/../../layouts/header.php';
?>
<div class="lacms-app-wrapper"><?php include __DIR__.'/../../layouts/sidebar.php'; ?><main class="lacms-main-content">
<div class="lo-head"><div><a class="small text-decoration-none" href="index.php"><i class="bi bi-arrow-left"></i> Agenda Registry</a><div class="lo-eyebrow mt-2"><?= e($agenda['agenda_reference']) ?></div><h1><?= e($agenda['title']) ?></h1><p><?= e($agenda['agenda_type']) ?> · <?= e($agenda['committee_name']?:'No committee') ?></p></div><div class="d-flex gap-2 flex-wrap"><span class="lo-status <?= $agenda['status']==='Finalized'?'good':($agenda['status']==='Cancelled'?'bad':($agenda['status']==='Under Review'?'warn':'')) ?>"><?= e($agenda['status']) ?></span><a class="btn btn-outline-secondary btn-sm" target="_blank" href="print.php?id=<?= $id ?>"><i class="bi bi-printer"></i></a></div></div>

<div class="row g-3">
<div class="col-xl-8">
<div class="card lo-card mb-3"><div class="card-header d-flex justify-content-between"><span>Agenda Information</span><?php if(lacmsOperationalManager()&&in_array($agenda['status'],['Draft','Under Review'],true)): ?><button class="btn btn-sm btn-primary" id="btnEdit"><i class="bi bi-pencil"></i> Edit</button><?php endif; ?></div><div class="card-body"><div class="lo-grid"><div><small>Date</small><strong><?= $agenda['agenda_date']?formatDate($agenda['agenda_date']):'Unscheduled' ?></strong></div><div><small>Time</small><strong><?= $agenda['start_time']?formatTime($agenda['start_time']):'—' ?><?= $agenda['end_time']?' - '.formatTime($agenda['end_time']):'' ?></strong></div><div><small>Venue</small><strong><?= e($agenda['venue']?:'TBA') ?></strong></div><div><small>Responsible Office</small><strong><?= e($agenda['office_name']?:'—') ?></strong></div><div><small>Created By</small><strong><?= e($agenda['created_name']?:'System') ?></strong></div><div><small>Finalized By</small><strong><?= e($agenda['finalized_name']?:'—') ?></strong></div></div><?php if($agenda['description']): ?><div class="lo-alert mt-3"><?= nl2br(e($agenda['description'])) ?></div><?php endif; ?></div></div>

<div class="card lo-card mb-3"><div class="card-header d-flex justify-content-between"><span>Agenda Items</span><?php if(lacmsOperationalManager()&&$agenda['status']!=='Finalized'&&$agenda['status']!=='Cancelled'): ?><button class="btn btn-sm btn-primary" id="btnAddItem"><i class="bi bi-plus"></i> Add Item</button><?php endif; ?></div><div class="card-body" id="itemList">
<?php if(!$agendaItems): ?><div class="text-muted small">No agenda items yet.</div><?php endif; ?>
<?php foreach($agendaItems as $item): ?><div class="lo-participant mb-2 agenda-sort-item" data-id="<?= (int)$item['id'] ?>"><div class="d-flex gap-2"><span class="lo-seq"><?= (int)$item['sequence_number'] ?></span><div><strong><?= e($item['title']) ?></strong><small><?= e(($item['agenda_section']?:'General').' · '.$item['priority_level'].' · '.$item['item_status']) ?><?= $item['legislative_reference']?' · '.e($item['legislative_reference']):'' ?></small><?php if($item['description']): ?><small><?= e(mb_strimwidth($item['description'],0,120,'…')) ?></small><?php endif; ?></div></div><?php if(lacmsOperationalManager()&&$agenda['status']!=='Finalized'&&$agenda['status']!=='Cancelled'): ?><div class="btn-group btn-group-sm"><button class="btn btn-outline-primary edit-item" data-row='<?= e(json_encode($item,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>'>Edit</button><button class="btn btn-outline-danger delete-item" data-id="<?= (int)$item['id'] ?>">Delete</button></div><?php endif; ?></div><?php endforeach; ?>
<?php if(lacmsOperationalManager()&&count($agendaItems)>1&&$agenda['status']!=='Finalized'&&$agenda['status']!=='Cancelled'): ?><button class="btn btn-outline-secondary btn-sm mt-2" id="btnSaveOrder">Save Current Order</button><?php endif; ?>
</div></div>

<div class="card lo-card mb-3"><div class="card-header">Agenda Documents</div><div class="card-body"><div class="list-group mb-3"><?php if(!$documents): ?><div class="list-group-item text-muted">No agenda documents uploaded.</div><?php endif; ?><?php foreach($documents as $d): ?><a class="list-group-item list-group-item-action" target="_blank" href="<?= e(UPLOAD_URL.$d['file_path']) ?>"><strong><?= e($d['file_name']) ?></strong><div class="small text-muted"><?= e($d['document_type'].' · '.$d['visibility']) ?><?= $d['item_title']?' · '.e($d['item_title']):'' ?> · <?= formatDateTime($d['uploaded_at']) ?></div></a><?php endforeach; ?></div><?php if(lacmsOperationalManager()): ?><form id="docForm" class="row g-2" enctype="multipart/form-data"><?= csrfField() ?><input type="hidden" name="agenda_id" value="<?= $id ?>"><div class="col-md-5"><input type="file" class="form-control form-control-sm" name="document" required></div><div class="col-md-3"><input class="form-control form-control-sm" name="document_type" value="Agenda Document"></div><div class="col-md-2"><select class="form-select form-select-sm" name="visibility"><option>Internal</option><option>Restricted</option><option>Public</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary btn-sm w-100">Upload</button></div></form><?php endif; ?></div></div>
</div>

<div class="col-xl-4">
<?php if(lacmsOperationalManager()): ?><div class="card lo-card mb-3"><div class="card-header">Agenda Workflow</div><div class="card-body d-grid gap-2">
<?php if($agenda['status']==='Draft'): ?><button class="btn btn-warning agenda-action" data-action="review">Send for Review</button><button class="btn btn-success agenda-action" data-action="finalize">Finalize Agenda</button><?php elseif($agenda['status']==='Under Review'): ?><button class="btn btn-success agenda-action" data-action="finalize">Finalize Agenda</button><?php elseif($agenda['status']==='Finalized'): ?><?php if(isAdmin()): ?><button class="btn btn-outline-warning agenda-action" data-action="reopen">Reopen</button><?php endif; ?><button class="btn btn-outline-secondary agenda-action" data-action="archive">Archive</button><a class="btn btn-primary" href="<?= e(appUrl('modules/calendar/index.php?agenda_id='.$id)) ?>">Schedule on Calendar</a><?php endif; ?>
<?php if(!in_array($agenda['status'],['Archived','Cancelled'],true)): ?><button class="btn btn-outline-danger agenda-action" data-action="cancel">Cancel Agenda</button><?php endif; ?>
</div></div><?php endif; ?>

<div class="card lo-card"><div class="card-header">Agenda History</div><div class="card-body lo-history"><?php if(!$historyRows): ?><div class="text-muted small">No history yet.</div><?php endif; ?><?php foreach($historyRows as $h): ?><div><strong><?= e($h['action']) ?> · <?= e($h['changed_name']?:'System') ?></strong><small><?= e(($h['previous_status']?:'—').' → '.($h['new_status']?:'—')) ?><?= $h['details']?'<br>'.e($h['details']):'' ?><br><?= formatDateTime($h['created_at']) ?></small></div><?php endforeach; ?></div></div>
</div>
</div>
</main></div>

<?php if(lacmsOperationalManager()): ?>
<div class="modal fade" id="editModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered modal-dialog-scrollable" style="max-width: 640px;"><div class="modal-content border-0 shadow-lg rounded-3"><form id="editForm"><?= csrfField() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="modal-header py-2 px-3 text-white" style="background: linear-gradient(135deg, #0f172a, #1e293b);"><div class="d-flex align-items-center gap-2"><div class="d-inline-flex align-items-center justify-content-center bg-white bg-opacity-10 text-white rounded-circle" style="width: 28px; height: 28px;"><i class="bi bi-pencil-square fs-6"></i></div><h6 class="modal-title fw-bold mb-0 text-white">Edit Agenda</h6></div><button class="btn-close btn-close-white btn-sm" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body p-3"><div class="row g-2"><div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Title *</label><input class="form-control form-control-sm" name="title" value="<?= e($agenda['title']) ?>" required></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Type</label><input class="form-control form-control-sm" name="agenda_type" value="<?= e($agenda['agenda_type']) ?>"></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Committee</label><select class="form-select form-select-sm" name="committee_id"><option value="">None</option><?php foreach($committees as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$agenda['committee_id']===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Office</label><select class="form-select form-select-sm" name="office_id"><option value="">None</option><?php foreach($offices as $o): ?><option value="<?= (int)$o['id'] ?>" <?= (int)$agenda['office_id']===(int)$o['id']?'selected':'' ?>><?= e($o['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Date</label><input type="date" class="form-control form-control-sm" name="agenda_date" value="<?= e($agenda['agenda_date']?:'') ?>"></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Start</label><input type="time" class="form-control form-control-sm" name="start_time" value="<?= e($agenda['start_time']?:'') ?>"></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">End</label><input type="time" class="form-control form-control-sm" name="end_time" value="<?= e($agenda['end_time']?:'') ?>"></div><div class="col-md-6"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Venue</label><input class="form-control form-control-sm" name="venue" value="<?= e($agenda['venue']?:'') ?>"></div><div class="col-md-6"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Meeting Link</label><input class="form-control form-control-sm" name="meeting_link" value="<?= e($agenda['meeting_link']?:'') ?>"></div><div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Description</label><textarea class="form-control form-control-sm" name="description" rows="2" style="min-height: 55px; max-height: 120px; font-size: 0.82rem;"><?= e($agenda['description']?:'') ?></textarea></div><div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Notes</label><textarea class="form-control form-control-sm" name="notes" rows="2" style="min-height: 50px; max-height: 100px; font-size: 0.82rem;"><?= e($agenda['notes']?:'') ?></textarea></div></div></div><div class="modal-footer py-2 px-3 bg-light border-top"><button class="btn btn-sm btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-sm btn-primary px-3 fw-semibold">Save Changes</button></div></form></div></div></div>

<div class="modal fade" id="itemModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered modal-dialog-scrollable" style="max-width: 640px;"><div class="modal-content border-0 shadow-lg rounded-3"><form id="itemForm"><?= csrfField() ?><input type="hidden" name="agenda_id" value="<?= $id ?>"><input type="hidden" name="item_id" id="i_id" value="0"><input type="hidden" name="mode" value="save"><div class="modal-header py-2 px-3 text-white" style="background: linear-gradient(135deg, #0f172a, #1e293b);"><div class="d-flex align-items-center gap-2"><div class="d-inline-flex align-items-center justify-content-center bg-white bg-opacity-10 text-white rounded-circle" style="width: 28px; height: 28px;"><i class="bi bi-list-check fs-6"></i></div><h6 class="modal-title fw-bold mb-0 text-white">Agenda Item</h6></div><button class="btn-close btn-close-white btn-sm" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body p-3"><div class="row g-2">
<div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Linked Legislative Item</label><select class="form-select form-select-sm" name="legislative_item_id" id="i_legislative"><option value="">None / Standalone Agenda Item</option><?php foreach($legislativeItems as $li): ?><option value="<?= (int)$li['id'] ?>"><?= e($li['reference_number'].' · '.$li['title'].' · '.$li['current_status']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Item No.</label><input class="form-control form-control-sm" name="item_number" id="i_number"></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Section</label><select class="form-select form-select-sm" name="agenda_section" id="i_section"><option>Call to Order</option><option>Approval of Minutes</option><option>Committee Reports</option><option>Old Business</option><option selected>New Business</option><option>Privilege Hour</option><option>Announcements</option><option>Other</option></select></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Priority</label><select class="form-select form-select-sm" name="priority_level" id="i_priority"><option>Low</option><option selected>Normal</option><option>High</option><option>Urgent</option></select></div>
<div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Item Title *</label><input class="form-control form-control-sm" name="title" id="i_title" required></div><div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Description</label><textarea class="form-control form-control-sm" name="description" id="i_description" rows="2" style="min-height: 55px; max-height: 120px; font-size: 0.82rem;"></textarea></div>
<div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Sponsor</label><select class="form-select form-select-sm" name="sponsor_user_id" id="i_sponsor"><option value="">None</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['full_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Presenter</label><select class="form-select form-select-sm" name="presenter_user_id" id="i_presenter"><option value="">None</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['full_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Committee</label><select class="form-select form-select-sm" name="committee_id" id="i_committee"><option value="">None</option><?php foreach($committees as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Est. Minutes</label><input type="number" min="1" class="form-control form-control-sm" name="estimated_minutes" id="i_minutes"></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Status</label><select class="form-select form-select-sm" name="item_status" id="i_status"><option>Pending</option><option>Ready</option><option>Deferred</option><option>Completed</option><option>Removed</option></select></div><div class="col-md-4"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Disposition</label><input class="form-control form-control-sm" name="disposition" id="i_disposition"></div><div class="col-12"><label class="form-label text-uppercase fw-semibold text-muted mb-1" style="font-size: 0.72rem; letter-spacing: 0.04em;">Notes</label><textarea class="form-control form-control-sm" name="notes" id="i_notes" rows="2" style="min-height: 50px; max-height: 100px; font-size: 0.82rem;"></textarea></div>
</div></div><div class="modal-footer py-2 px-3 bg-light border-top"><button class="btn btn-sm btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-sm btn-primary px-3 fw-semibold">Save Agenda Item</button></div></form></div></div></div>

<script>
document.addEventListener('DOMContentLoaded',function(){
 const editModalEl=document.getElementById('editModal'),itemModalEl=document.getElementById('itemModal');
 const editModal=editModalEl?new bootstrap.Modal(editModalEl):null,itemModal=itemModalEl?new bootstrap.Modal(itemModalEl):null;
 const editForm=document.getElementById('editForm'),itemForm=document.getElementById('itemForm'),docForm=document.getElementById('docForm');
 const editBtn=document.getElementById('btnEdit');if(editBtn)editBtn.onclick=()=>editModal.show();
 if(editForm)editForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('ajax_save.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new FormData(editForm)}).then(x=>x.json());if(r.success)location.reload();else Swal.fire('Agenda Error',r.message,'error');};
 const add=document.getElementById('btnAddItem');if(add)add.onclick=()=>{itemForm.reset();document.getElementById('i_id').value='0';itemModal.show();};
 document.querySelectorAll('.edit-item').forEach(b=>b.onclick=function(){const x=JSON.parse(this.dataset.row);itemForm.reset();i_id.value=x.id;i_legislative.value=x.legislative_item_id||'';i_number.value=x.item_number||'';i_section.value=x.agenda_section||'New Business';i_priority.value=x.priority_level||'Normal';i_title.value=x.title||'';i_description.value=x.description||'';i_sponsor.value=x.sponsor_user_id||'';i_presenter.value=x.presenter_user_id||'';i_committee.value=x.committee_id||'';i_minutes.value=x.estimated_minutes||'';i_status.value=x.item_status||'Pending';i_disposition.value=x.disposition||'';i_notes.value=x.notes||'';itemModal.show();});
 if(itemForm)itemForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('ajax_item.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new FormData(itemForm)}).then(x=>x.json());if(r.success)location.reload();else Swal.fire('Agenda Item Error',r.message,'error');};
 document.querySelectorAll('.delete-item').forEach(b=>b.onclick=async function(){const c=await Swal.fire({title:'Delete agenda item?',showCancelButton:true,icon:'warning'});if(!c.isConfirmed)return;const fd=new FormData();fd.append('csrf_token','<?= e(csrfToken()) ?>');fd.append('agenda_id','<?= $id ?>');fd.append('item_id',this.dataset.id);fd.append('mode','delete');const r=await fetch('ajax_item.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:fd}).then(x=>x.json());if(r.success)location.reload();else Swal.fire('Agenda Item Error',r.message,'error');});
 const orderBtn=document.getElementById('btnSaveOrder');if(orderBtn)orderBtn.onclick=async()=>{const order=[...document.querySelectorAll('.agenda-sort-item')].map(x=>x.dataset.id);const fd=new FormData();fd.append('csrf_token','<?= e(csrfToken()) ?>');fd.append('agenda_id','<?= $id ?>');fd.append('order',JSON.stringify(order));const r=await fetch('ajax_reorder.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:fd}).then(x=>x.json());if(r.success)location.reload();else Swal.fire('Order Error',r.message,'error');};
 document.querySelectorAll('.agenda-action').forEach(b=>b.onclick=async function(){let notes='';if(['reopen','cancel'].includes(this.dataset.action)){const x=await Swal.fire({title:this.dataset.action==='cancel'?'Cancel agenda?':'Reopen finalized agenda?',input:'textarea',inputLabel:'Reason',showCancelButton:true,inputValidator:v=>!v?'Reason is required':undefined});if(!x.isConfirmed)return;notes=x.value;}else{const x=await Swal.fire({title:this.dataset.action.charAt(0).toUpperCase()+this.dataset.action.slice(1)+' agenda?',showCancelButton:true});if(!x.isConfirmed)return;}const fd=new FormData();fd.append('csrf_token','<?= e(csrfToken()) ?>');fd.append('agenda_id','<?= $id ?>');fd.append('action',this.dataset.action);fd.append('notes',notes);const r=await fetch('ajax_transition.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:fd}).then(x=>x.json());if(r.success)location.reload();else Swal.fire('Workflow Error',r.message,'error');});
 if(docForm)docForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('ajax_upload_document.php',{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new FormData(docForm)}).then(x=>x.json());if(r.success)location.reload();else Swal.fire('Upload Error',r.message,'error');};
});
</script>
<?php endif; ?>
